mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  vec3 q = p - vec3(0.0, 0.0, 4.0);
  vec3 b = abs(q) - vec3(0.35, 1.9, 0.35);
  float obelisk = max(b.x, max(b.y, b.z));
  float sea = p.y + 0.5 + 0.03 * sin(p.x * 3.0 + time) * cos(p.z * 3.0);
  return min(obelisk, sea);
}
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 0.8, -3.5);
  vec3 rd = normalize(vec3(p, 1.5));
  rd.yz = rot(-0.15) * rd.yz;
  float t = 0.0, glow = 0.0;
  for (int i = 0; i < 48; i++) {
    float d = map(ro + rd * t);
    glow += 0.01 / (0.04 + abs(d) * abs(d) * 14.0);
    if (d < 0.003 || t > 12.0) break;
    t += d * 0.8;
  }
  vec3 col = mix(vec3(0.8, 0.15, 0.05), vec3(0.02, 0.01, 0.04), clamp(rd.y * 2.0 + 0.3, 0.0, 1.0));
  col += glow * vec3(1.0, 0.4, 0.1) * (0.8 + 0.3 * bass);
  col = (col * (2.51 * col + 0.03)) / (col * (2.43 * col + 0.59) + 0.14);
  ret = col;
}
